contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test: fund C by calling its fallback via a plain call to address(c).call is NOT allowed for state-changing on c per constraints,
    // so instead we send Ether to C by invoking c.sendMoney with target = address(c) which will trigger c.fallback and change state.
    // Note: sendMoney is onlyOwner, but the constructor of C sets owner to msg.sender (the deployer), which is the test harness, so this InvMutTest (deployer) is owner.
    // The property asserts behavior for the case when this contract is NOT the owner; to achieve that we will read owner and then reason about the non-owner case.

    function run(uint fundAmount, uint withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= fundAmount);

        // Record before-values
        uint beforeCBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        address owner = c.owner(); if (__ESBMC_reverted()) return;

        // Fund C by having the owner (this contract) call sendMoney to target C, which will invoke fallback and increase depositsCount and balance.
        // This is a state-changing top-level call on c.
        c.sendMoney(address(c), fundAmount); if (__ESBMC_reverted()) return;

        // Record after funding
        uint afterFundCBalance = address(c).balance;
        uint afterFundDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // Attempt withdrawAll and withdraw, catching reverts (each is a top-level call or try-catch)
        bool withdrewAllReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewAllReverted = true;
        } else {
            withdrewAllReverted = false;
        }

        bool withdrawReverted;
        c.withdraw(withdrawAmount); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        // General rule: if this contract is NOT the owner observed from c.owner(), then both withdraw calls must revert
        // and they must not have changed C's balance or depositsCount compared to after funding.
        assert(
            (address(this) == owner) || (
                withdrewAllReverted && withdrawReverted
                && address(c).balance == afterFundCBalance
                && c.depositsCount() == afterFundDeposits
            )
        );
    }

    receive() external payable {}
}

