// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 fundAmount, uint256 withdrawAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fundAmount);
        uint beforeCBalance = address(c).balance;
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        try c.sendMoney(address(c), fundAmount) {} catch { return; }
        uint afterFundCBalance = address(c).balance;
        uint256 afterFundDeposits;
        try c.depositsCount() returns (uint256 __r) { afterFundDeposits = __r; } catch { return; }
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        assertTrue((address(this) == owner) || (
                withdrewAllReverted && withdrawReverted
                && address(c).balance == afterFundCBalance
                && c.depositsCount() == afterFundDeposits
            ));
    }

    function testFuzz_run(uint256 fundAmount, uint256 withdrawAmount) public {
        _run(fundAmount, withdrawAmount);
    }

    receive() external payable {}
}
